import {SpatialStage,THREE} from './spatial-stage.js';
import {clusterLayout,family,families} from './colour-model.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function glowTexture(){const c=document.createElement('canvas');c.width=c.height=128;const x=c.getContext('2d'),g=x.createRadialGradient(64,64,0,64,64,64);g.addColorStop(0,'#ffffffff');g.addColorStop(.13,'#ffffffbd');g.addColorStop(.34,'#ffffff32');g.addColorStop(1,'#ffffff00');x.fillStyle=g;x.fillRect(0,0,128,128);return new THREE.CanvasTexture(c)}
export class ColourCluster extends SpatialStage{
 constructor(host,{artifacts,onDetail}){
  host.innerHTML=`<div class="spatial-canvas"></div><div class="colour-hubs"></div><div class="spatial-heading colour-heading"><span class="spatial-kicker">CHROMATIC CONSTELLATIONS / 三维颜色图谱</span><h2>颜色，让器物相遇。</h2><p>每一颗主点，都是一件器物。<br>靠近，发现它身边的其他颜色。</p></div><div class="spatial-tools"><button data-colour="rotate" aria-pressed="false">缓缓旋转</button><button data-colour="home">全景</button><button data-colour="out" aria-label="缩小颜色点云">−</button><button data-colour="in" aria-label="放大颜色点云">＋</button></div><div class="colour-family-nav" aria-label="聚焦色群">${families.map(f=>`<button data-family="${f.id}" style="--dot:${f.hex}" aria-pressed="false"><i></i>${f.name}</button>`).join('')}</div><div class="colour-hover" hidden></div><div class="colour-cloud-caption"><span>旋转 · 拖动 · 缩放</span><small>拖动旋转 / 右键或双指平移 / 滚轮缩放 / 点器物进入档案</small></div><div class="spatial-bottom"><p class="spatial-status"></p><details><summary>颜色如何聚合？</summary><p>将器物全部照片色卡按面积占比，计算感知色彩空间 OKLab 的加权中心。红黑兼有的器物会落在两色之间。相邻点稍作三维错开，避免遮挡；位置表示配色相近，不表示历史关系。主点是占比最高的照片颜色，环绕的小点是它的其他颜色。</p><a href="colours.html">逐个查看色号与出处 ↗</a></details></div>`;
  super(host);this.artifacts=artifacts;this.onDetail=onDetail;this.items=clusterLayout(artifacts);this.ray=new THREE.Raycaster();this.pointer=new THREE.Vector2();this.texture=glowTexture();this.pickables=[];this.matches=new Set(artifacts.map(a=>a.id));this.focusedFamily=null;this.hubs=[];
  this.controls.minDistance=28;this.controls.maxDistance=480;this.controls.autoRotateSpeed=.35;
  this.home();this.build();this.bind();host.dataset.ready='true';
 }
 home(){const narrow=this.host.getBoundingClientRect().width<600;this.resetCamera(narrow?[232,140,275]:[125,73,191],narrow?[12,15,30]:[-20,0,25]);this.controls.autoRotate=false;this.host.querySelector('[data-colour=rotate]').setAttribute('aria-pressed','false');this.targetMove=null}
 build(){
  const geometry=new THREE.SphereGeometry(1,14,10);
  for(const n of this.items){const group=new THREE.Group();group.position.fromArray(n.p);this.scene.add(group);n.group=group;const color=n.palette[0].hex;
   n.core=new THREE.Mesh(geometry,new THREE.MeshBasicMaterial({color,transparent:true,opacity:1}));n.core.scale.setScalar(1.45);n.core.userData.item=n;group.add(n.core);this.pickables.push(n.core);
   n.glow=new THREE.Sprite(new THREE.SpriteMaterial({map:this.texture,color,transparent:true,opacity:.50,depthWrite:false,blending:THREE.AdditiveBlending}));n.glow.scale.set(10,10,1);group.add(n.glow);
   n.ring=new THREE.Sprite(new THREE.SpriteMaterial({map:this.texture,color:'#e1d3b2',transparent:true,opacity:.15,depthWrite:false}));n.ring.scale.set(5,5,1);group.add(n.ring);
   n.satellites=n.palette.slice(1).map((c,i)=>{const angle=i*2.399+n.p[1],r=2.8+i*.38,s=new THREE.Mesh(geometry,new THREE.MeshBasicMaterial({color:c.hex,transparent:true}));s.position.set(Math.cos(angle)*r,Math.sin(angle)*r,Math.sin(angle*1.9)*1.8);s.scale.setScalar(.48+Math.sqrt(c.weight)*.65);s.userData.item=n;group.add(s);this.pickables.push(s);return s});
  }
  for(const f of families){const entries=this.items.filter(n=>n.palette.some(c=>family(c.hex)===f.id&&c.weight>.08));if(!entries.length){this.host.querySelector(`[data-family=${f.id}]`).disabled=true;continue}const p=new THREE.Vector3();entries.forEach(n=>p.add(n.group.position));p.divideScalar(entries.length);
   const haze=new THREE.Sprite(new THREE.SpriteMaterial({map:this.texture,color:f.hex,transparent:true,opacity:.12,depthWrite:false,blending:THREE.AdditiveBlending}));haze.position.copy(p);haze.scale.set(95,95,1);this.scene.add(haze);
   const el=document.createElement('span');el.className='colour-hub';el.textContent=f.name+' · '+entries.length;el.style.setProperty('--hub',f.hex);this.host.querySelector('.colour-hubs').append(el);this.hubs.push({f,p,el,haze});
  }
  this.updateOpacity();
 }
 setFilter({matchedIds}){this.matches=matchedIds;this.updateOpacity()}
 updateOpacity(){let count=0;for(const n of this.items){const eligible=this.matches.has(n.a.id),selected=!this.focusedFamily||n.palette.some(c=>family(c.hex)===this.focusedFamily&&c.weight>.08);n.active=eligible&&selected;if(n.active)count++;n.core.material.opacity=n.active?1:.08;n.glow.material.opacity=n.active?.5:.015;n.ring.material.opacity=n.active?.15:.025;n.satellites.forEach(s=>s.material.opacity=n.active?.9:.05)}this.host.querySelector('.spatial-status').textContent=`${count} / ${this.items.length} 件器物亮起 · ${this.items.reduce((s,n)=>s+n.palette.length,0)} 个照片色样`;this.host.querySelectorAll('[data-family]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.family===this.focusedFamily)));if(this.hovered&&!this.hovered.active)this.show(null)}
 hit(e){const r=this.renderer.domElement.getBoundingClientRect();this.pointer.set((e.clientX-r.left)/r.width*2-1,1-(e.clientY-r.top)/r.height*2);this.ray.setFromCamera(this.pointer,this.camera);return this.ray.intersectObjects(this.pickables).find(h=>h.object.userData.item.active)?.object.userData.item}
 show(n){if(n===this.hovered)return;this.hovered=n;const tip=this.host.querySelector('.colour-hover');tip.hidden=!n;this.renderer.domElement.style.cursor=n?'pointer':'grab';if(!n)return;tip.innerHTML=`<img src="${esc(n.a.displayImage||n.a.image)}" alt=""><div><span class="spatial-kicker">${esc(n.a.material)} / ${esc(n.a.city)}</span><strong>${esc(n.a.title)}</strong><p>${n.palette.map(c=>`<i style="background:${c.hex}" title="${c.hex}"></i>`).join('')}</p><small>点击主点，打开器物档案 ↗</small></div>`}
 focusItem(a){const n=this.items.find(x=>x.a.id===a.id);if(!n)return;this.targetMove={target:n.group.position.clone(),camera:n.group.position.clone().add(new THREE.Vector3(45,24,95))};this.show(n)}
 jumpEra(id){const n=this.items.find(x=>x.a.era===id&&x.active);if(n)this.focusItem(n.a)}
 bind(){const canvas=this.renderer.domElement;let down=null;canvas.addEventListener('pointerdown',e=>{down={id:e.pointerId,x:e.clientX,y:e.clientY};this.targetMove=null;this.show(null)});canvas.addEventListener('pointermove',e=>{if(!e.buttons)this.show(this.hit(e))});canvas.addEventListener('pointerup',e=>{if(down&&e.pointerId===down.id&&Math.hypot(e.clientX-down.x,e.clientY-down.y)<6){const n=this.hit(e);if(n)this.onDetail(n.a)}down=null});canvas.addEventListener('pointercancel',()=>down=null);canvas.addEventListener('pointerleave',()=>{if(!this.targetMove)this.show(null)});
  this.host.querySelectorAll('[data-colour]').forEach(b=>b.onclick=()=>{const id=b.dataset.colour;if(id==='home'){this.home();this.focusedFamily=null;this.updateOpacity();this.show(null)}else if(id==='rotate'){this.controls.autoRotate=!this.controls.autoRotate;b.setAttribute('aria-pressed',String(this.controls.autoRotate))}else{const v=this.camera.position.clone().sub(this.controls.target).multiplyScalar(id==='in'?.8:1.25);v.clampLength(this.controls.minDistance,this.controls.maxDistance);this.camera.position.copy(this.controls.target).add(v)}});
  this.host.querySelectorAll('[data-family]').forEach(b=>b.onclick=()=>{this.focusedFamily=this.focusedFamily===b.dataset.family?null:b.dataset.family;this.updateOpacity();const hub=this.hubs.find(h=>h.f.id===this.focusedFamily);if(hub)this.targetMove={target:hub.p.clone(),camera:hub.p.clone().add(new THREE.Vector3(55,32,140))};else this.home()});
 }
 navigationState(){return {...super.navigationState(),family:this.focusedFamily}}
 restore(s){super.restore(s);if(families.some(f=>f.id===s?.family))this.focusedFamily=s.family;this.updateOpacity()}
 frame(){if(this.targetMove){const k=this.reduced?1:.065;this.camera.position.lerp(this.targetMove.camera,k);this.controls.target.lerp(this.targetMove.target,k);if(this.camera.position.distanceTo(this.targetMove.camera)<.1)this.targetMove=null}const placed=[];for(const h of this.hubs){const q=this.project(h.p);h.el.hidden=!q.visible||h.f.id!==this.focusedFamily;if(h.el.hidden)continue;let y=q.y+26;for(let attempt=0;attempt<12&&placed.some(p=>Math.abs(p.x-q.x)<92&&Math.abs(p.y-y)<26);attempt++)y+=26;placed.push({x:q.x,y});h.el.style.left=q.x+'px';h.el.style.top=Math.min(this.h-92,y)+'px'}if(this.hovered){const q=this.project(this.hovered.group.position),tip=this.host.querySelector('.colour-hover');tip.hidden=!q.visible;tip.style.left=Math.max(8,Math.min(this.w-tip.offsetWidth-8,q.x+19))+'px';tip.style.top=Math.max(95,Math.min(this.h-tip.offsetHeight-64,q.y-70))+'px';this.hovered.core.scale.setScalar(2)}for(const n of this.items)if(n!==this.hovered)n.core.scale.setScalar(1.45)}
}
